#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define CONVERSION_REGISTER 0x00
#define CONFIG_REGISTER 0x01
#define CONFIG_VALUE 0x8583 // 0.5s conversion, single-shot mode

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int file;
    uint16_t data;
    struct sigaction action;
    struct timespec req, rem;

    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return EXIT_FAILURE;
    }

    if (write(file, &CONFIG_REGISTER, 1) != 1) {
        perror("Failed to write to i2c slave");
        return EXIT_FAILURE;
    }

    if (write(file, &CONFIG_VALUE, 2) != 2) {
        perror("Failed to write to i2c slave");
        return EXIT_FAILURE;
    }

    req.tv_sec = 0;
    req.tv_nsec = 500000000; // 0.5 seconds

    while (!stop) {
        if (nanosleep(&req, &rem) == -1) {
            perror("nanosleep failed");
            return EXIT_FAILURE;
        }

        if (write(file, &CONVERSION_REGISTER, 1) != 1) {
            perror("Failed to write to i2c slave");
            return EXIT_FAILURE;
        }

        if (read(file, &data, 2) != 2) {
            perror("Failed to read from i2c slave");
            return EXIT_FAILURE;
        }

        printf("ADC value: %d\n", data);
    }

    close(file);
    return EXIT_SUCCESS;
}

