#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define CONVERSION_REGISTER 0x00
#define CONFIGURATION_REGISTER 0x01
#define OS_BIT 0x80
#define PGA_4_096 0x60
#define DR_128SPS 0x08

int main() {
    int file;
    uint8_t buffer[2];
    uint16_t reading;
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];

    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    // Configure the ADC
    buffer[0] = CONFIGURATION_REGISTER;
    buffer[1] = OS_BIT | PGA_4_096 | DR_128SPS;
    messages[0].addr = ADS1115_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if (ioctl(file, I2C_RDWR, &packets) < 0) {
        perror("Failed to write to the i2c bus");
        exit(1);
    }

    while (1) {
        // Wait for conversion to complete
        usleep(100000);

        // Read the ADC
        messages[0].addr = ADS1115_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = &buffer[0];
        messages[1].addr = ADS1115_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 2;
        messages[1].buf = &buffer[1];

        packets.msgs = messages;
        packets.nmsgs = 2;

        if (ioctl(file, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        // Combine the two bytes into a 16-bit integer
        reading = (buffer[0] << 8) | buffer[1];

        // Print the reading
        printf("ADC reading: %d\n", reading);

        // Repeat once every 0.1 seconds
        usleep(100000);
    }

    close(file);
    return 0;
}

