#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int gpio = 18;
    int frequency = 50; // 50 Hz
    int duty_cycle = 128; // 50% duty cycle

    if (gpioSetPWMfrequency(gpio, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMdutycycle(gpio, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO %d with frequency %d Hz and duty cycle %d%%\n", gpio, frequency, duty_cycle * 100 / 255);

    while (1) {
        sleep(1); // sleep for 1 second
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define SLEEP_TIME 60

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line_trig, *line_echo;
    uint8_t value;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto close_chip;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get echo line\n");
        goto close_chip;
    }

    ret = gpiod_line_request_output(line_trig, "trigger", 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        goto close_chip;
    }

    ret = gpiod_line_request_input(line_echo, "echo");
    if (ret) {
        fprintf(stderr, "Failed to request echo line as input\n");
        goto close_chip;
    }

    while (true) {
        ret = gpiod_line_set_value(line_trig, 1);
        if (ret) {
            fprintf(stderr, "Failed to set trigger line high\n");
            goto close_chip;
        }

        usleep(10 * 1000); // 10 microseconds

        ret = gpiod_line_set_value(line_trig, 0);
        if (ret) {
            fprintf(stderr, "Failed to set trigger line low\n");
            goto close_chip;
        }

        while (true) {
            ret = gpiod_line_get_value(line_echo, &value);
            if (ret) {
                fprintf(stderr, "Failed to get echo line value\n");
                goto close_chip;
            }

            if (value == 0) {
                break;
            }

            usleep(100); // 100 microseconds
        }

        printf("Distance: %d cm\n", value * 58); // Assuming the sensor is in cm mode

        sleep(SLEEP_TIME);
    }

close_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

