#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 18

static void cleanup(gpiod_chip *chip, gpiod_line *line) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

static void handle_interrupt(int signum) {
    printf("Interrupt received, exiting...\n");
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for graceful exit
    signal(SIGINT, handle_interrupt);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup(chip, NULL);
        return EXIT_FAILURE;
    }

    // Request line request
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        cleanup(chip, line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle GPIO line
        ret = gpiod_line_set_value(line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            cleanup(chip, line);
            return EXIT_FAILURE;
        }
        printf("GPIO line set to 1\n");

        sleep(1);

        ret = gpiod_line_set_value(line, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            cleanup(chip, line);
            return EXIT_FAILURE;
        }
        printf("GPIO line set to 0\n");

        sleep(1);
    }

    // Cleanup
    cleanup(chip, line);
    return EXIT_SUCCESS;
}

