#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDRESS 0x40
#define SI7021_MEASURE_TEMP_HOLD_MASTER 0xE3
#define SI7021_MEASURE_HUMIDITY_HOLD_MASTER 0xE5

int main() {
    int file;
    uint8_t buffer[2];
    float temperature, humidity;
    int16_t raw_temperature, raw_humidity;
    char *filename = "/dev/i2c-1";

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, SI7021_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    while (true) {
        // Read temperature
        if (write(file, &SI7021_MEASURE_TEMP_HOLD_MASTER, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        usleep(500000); // Wait for the measurement to complete

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        raw_temperature = (buffer[0] << 8) | buffer[1];
        temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

        // Read humidity
        if (write(file, &SI7021_MEASURE_HUMIDITY_HOLD_MASTER, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        usleep(500000); // Wait for the measurement to complete

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        raw_humidity = (buffer[0] << 8) | buffer[1];
        humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        sleep(5); // Wait for 5 seconds
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONVERSION 0x01
#define ADS1115_CONFIG 0x01
#define ADS1115_DRDY 4

int main() {
    int file;
    uint8_t buffer[2];
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    // Open the I2C bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Connect to the ADS1115
    if (ioctl(file, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to connect to the ADS1115");
        return EXIT_FAILURE;
    }

    // Set up the GPIO chip and line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, ADS1115_DRDY);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    // Set up the GPIO line for input
    if (gpiod_line_request_input(line, "ADS1115_DRDY") < 0) {
        perror("Failed to request GPIO line");
        return EXIT_FAILURE;
    }

    // Configure the ADS1115
    buffer[0] = ADS1115_CONFIG;
    buffer[1] = ADS1115_CONVERSION;
    if (write(file, buffer, 2) != 2) {
        perror("Failed to write to the ADS1115");
        return EXIT_FAILURE;
    }

    // Read the ADC values
    for (int i = 0; i < 3; i++) {
        // Wait for the conversion to complete
        while (gpiod_line_get_value(line) != 0);

        // Read the ADC value
        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the ADS1115");
            return EXIT_FAILURE;
        }

        // Print the ADC value
        value = (buffer[0] << 8) | buffer[1];
        printf("ADC value: %d\n", value);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(file);

    return EXIT_SUCCESS;
}

