#define GPIO_PIN 17

static void cleanup(gpiod_chip *chip, gpiod_line *line) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

static void exit_handler(gpiod_chip *chip, gpiod_line *line) {
    cleanup(chip, line);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup(chip, NULL);
        return EXIT_FAILURE;
    }

    // Request line request
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        perror("Failed to request GPIO line as output");
        cleanup(chip, line);
        return EXIT_FAILURE;
    }

    // Set up exit handler
    atexit((void (*)(void))exit_handler);
    signal(SIGINT, SIG_DFL);

    // Main loop
    while (1) {
        // Toggle GPIO line
        ret = gpiod_line_set_value(line, 1);
        if (ret) {
