#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_27 27
#define SLEEP_TIME 50 // in milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;

static void cleanup_and_exit(int exit_code) {
    gpiod_line_request_output_bulk(lines, "off", 0);
    gpiod_chip_close(chip);
    exit(exit_code);
}

static void handle_interrupt(int signum) {
    cleanup_and_exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_interrupt;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.offsets[0] = GPIO_PIN_17;
    lines.offsets[1] = GPIO_PIN_18;
    lines.offsets[2] = GPIO_PIN_27;
    lines.count = 3;

    if (gpiod_line_request_output_bulk(chip, lines, "on") < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_set_value_bulk(chip, lines, 1);
        usleep(SLEEP_TIME * 1000);
        gpiod_line_set_value_bulk(chip, lines, 0);
        usleep(SLEEP_TIME * 1000);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

