#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_WAIT_TIME 5000000 // 5 seconds

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line_trig, *line_echo;
    uint64_t start_time, end_time, current_time;
    int distance;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto cleanup;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get echo line\n");
        goto cleanup;
    }

    gpiod_line_request_input(line_trig, "HC-SR04 Trigger");
    gpiod_line_request_input(line_echo, "HC-SR04 Echo");

    while (true) {
        gpiod_line_set_value(line_trig, 1);
        usleep(10);
        gpiod_line_set_value(line_trig, 0);

        start_time = 0;
        end_time = 0;

        while (true) {
            current_time = gpiod_line_get_value(line_echo);
            if (current_time == 1 && start_time == 0) {
                start_time = gettime();
            } else if (current_time == 0 && start_time != 0) {
                end_time = gettime();
                break;
            }

            if (end_time != 0) {
                break;
            }

            usleep(100);
        }

        if (end_time == 0) {
            printf("Timeout\n");
            continue;
        }

        distance = (end_time - start_time) / 58;
        printf("Distance: %d cm\n", distance);

        sleep(1);
    }

cleanup:
    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

