#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>

#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyS0"
#define _POSIX_SOURCE 1 /* POSIX compliant source */

int main(void)
{
    int fd;
    struct termios oldtio, newtio;
    char buf[255];
    int n;

    /* open the device */
    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    /* save current port settings */
    if (tcgetattr(fd, &oldtio) == -1) {
        perror("tcgetattr");
        exit(-1);
    }

    /* set new port settings for canonical input processing */
    memset(&newtio, 0, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical, no echo,...) */
    newtio.c_lflag = 0;

    /* control characters */
    newtio.c_cc[VTIME] = 0; /* inter-character timer unused */
    newtio.c_cc[VMIN] = 1;  /* blocking read until 1 character arrives */

    /* 
     * VTIME e VMIN devono essere settati per la select()
     * non bloccante, altrimenti read() restituisce 0
     */
    newtio.c_cc[VTIME] = 10; /* inter-character timer unused */
    newtio.c_cc[VMIN] = 0;  /* blocking read until 1 character arrives */

    /* now clean the modem line and activate the settings for the port */
    tcflush(fd, TCIFLUSH);
    if (tcsetattr(fd, TCSANOW, &newtio) == -1) {
        perror("tcsetattr");
        exit(-1);
    }

    /* 
     * read blocks until either a single character arrives, or the timeout
     * (3 seconds) expires, after which the process is terminated.
     */
    while (1) {
        n = read(fd, buf, sizeof(buf));
        if (n < 0) {
            if (errno == EAGAIN) {
                printf("No data available\n");
            } else {
                perror("read");
                exit(-1);
            }
        } else {
            buf[n] = 0; /* set end of string, so we can printf */
            printf("%s", buf);
        }
    }

    /* restore the old port settings */
    tcsetattr(fd, TCSANOW, &oldtio);

    close(fd);
    return 0;
}

