#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <libgpiod.h>

#define DHT11_PIN 4
#define DHT11_TIMEOUT 1000

static struct gpiod_chip *chip;
static struct gpiod_line *line;

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int read_dht11(uint8_t *data) {
    int ret;
    uint8_t laststate = HIGH;
    uint8_t counter = 0;
    uint8_t j = 0, i;

    *data = 0;

    gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_set_edge_detection(line, GPIOD_LINE_EVENT_BOTH_EDGES);
    gpiod_line_enable_event_wait(line);

    while (1) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", strerror(-ret));
            return -1;
        }

        uint8_t level = gpiod_line_get_value(line);

        if (level == laststate) {
            counter++;
        } else {
            if (counter >= 50) {
                *data |= (1 << (7 - j));
            }
            j++;
            counter = 0;
            laststate = level;

            if (j >= 8) {
                break;
            }
        }
    }

    gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_value(line, LOW);
    gpiod_line_event_wait(line, GPIOD_LINE_EVENT_BOTH_EDGES);

    return 0;
}

int main(void) {
    int ret;
    uint8_t data;

    atexit(cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    ret = read_dht11(&data);
    if (ret < 0) {
        return EXIT_FAILURE;
    }

    printf("DHT11 data: %d\n", data);

    return EXIT_SUCCESS;
}

