#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    int gpio[3] = {2, 3, 18};
    int i;
    int state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        if (gpioSetPWMfrequency(gpio[i], 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio[i]);
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(gpio[i], 100) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", gpio[i]);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (i = 0; i < 3; i++) {
            if (gpioSetPWMdutycycle(gpio[i], state) < 0) {
                fprintf(stderr, "Failed to set PWM dutycycle for GPIO %d\n", gpio[i]);
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", gpio[i], state);
        }

        state = (state + 10) % 101; // Increment state by 10, wrap around at 100

        sleep(1500000); // Sleep for 0.15 seconds
    }

    gpioTerminate(); // Clean up on exit

    return EXIT_SUCCESS;
}

