#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyS0"
#define _POSIX_SOURCE 1 /* POSIX compliant source */
#define FALSE 0
#define TRUE 1

volatile int STOP = FALSE;

void signal_handler_IO(int status);
void write_to_port(int fd, const char *str);

int main(void)
{
    int fd;
    struct termios oldtio, newtio;
    char buf[255];
    int n;

    /* open the device */
    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    /* save current port settings */
    tcgetattr(fd, &oldtio);

    /* set new port settings for canonical input processing */
    bzero(&newtio, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical, no echo,...) */
    newtio.c_lflag = 0;
    newtio.c_cc[VTIME]    = 0;   /* inter-character timer unused */
    newtio.c_cc[VMIN]     = 1;   /* blocking read until 1 character arrives */

    /* 
     * VTIME e VMIN devono essere settati per la select 
     * non bloccante, altrimenti read() attende per sempre
     */
    tcflush(fd, TCIFLUSH);

    /* 
     * abilita la ricezione di segnali di I/O 
     * e la gestione del segnale di blocco
     */
    fcntl(fd, F_SETOWN, getpid());
    fcntl(fd, F_SETFL, FASYNC);

    /* install the signal handler before making the device asynchronous */
    signal(SIGIO, signal_handler_IO);

    /* make the device asynchronous */
    tcsetattr(fd, TCSANOW, &newtio);

    /* wait for input */
    while (STOP == FALSE) {
        /* wait for input */
        fd_set set;
        struct timeval timeout;
        int rv;

        FD_ZERO(&set);
        FD_SET(fd, &set);

        /* set timeout */
        timeout.tv_sec = 5;
        timeout.tv_usec = 0;

        rv = select(fd + 1, &set, NULL, NULL, &timeout);
        if (rv == -1)
            perror("select"); /* an error accurred */
        else if (rv == 0)
            printf("Timeout occurred!"); /* a timeout occured */
        else {
            n = read(fd, buf, sizeof(buf));
            if (n < 0)
                perror("read");
            else {
                buf[n] = 0; /* set end of string */
                printf("%s", buf);
            }
        }
    }

    /* restore old port settings */
    tcsetattr(fd, TCSANOW, &oldtio);

    close(fd);
    return 0;
}

void signal_handler_IO(int status)
{
    printf("Signal received\n");
    STOP = TRUE;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define GPIO_PIN_17 17
#define SLEEP_TIME 10000 // 0.01 seconds

static bool running = true;

void interrupt_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    // Register interrupt handler
    signal(SIGINT, interrupt_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line for GPIO 17
    struct gpiod_line_request request = {
        .consumer = "my_program",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_value = 0,
    };
    if (gpiod_line_request(line, &request) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Set GPIO 4 to high
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 4 set to high\n");

        // Sleep for a short time
        usleep(SLEEP_TIME);

        // Set GPIO 4 to low
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 4 set to low\n");

        // Sleep for a short time
        usleep(SLEEP_TIME);
    }

    // Release line
    gpiod_line_release(line);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

