#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PATH "/sys/class/gpio"
#define W1_PATH "/sys/bus/w1/devices"

int fd;
char *device_path;

void cleanup(int signum) {
    if (device_path) {
        close(fd);
        free(device_path);
    }
    exit(1);
}

int main() {
    struct dirent *dir;
    DIR *d = opendir(W1_PATH);
    if (!d) {
        perror("Failed to open w1 devices directory");
        return 1;
    }

    while ((dir = readdir(d)) != NULL) {
        if (strstr(dir->d_name, "28-") != NULL) {
            device_path = malloc(strlen(W1_PATH) + strlen(dir->d_name) + 2);
            if (!device_path) {
                perror("Failed to allocate memory");
                closedir(d);
                return 1;
            }
            sprintf(device_path, "%s/%s/w1_slave", W1_PATH, dir->d_name);
            break;
        }
    }
    closedir(d);

    if (!device_path) {
        fprintf(stderr, "DS18B20 sensor not found\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        char buffer[256];
        ssize_t bytes_read;
        int crc_error = 0;

        fd = open(device_path, O_RDONLY);
        if (fd < 0) {
            perror("Failed to open device");
            return 1;
        }

        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            perror("Failed to read from device");
            close(fd);
            return 1;
        }

        buffer[bytes_read] = '\0';

        if (strstr(buffer, "NO") != NULL) {
            fprintf(stderr, "Device not found\n");
            close(fd);
            return 1;
        }

        if (strstr(buffer, "CRC") != NULL) {
            fprintf(stderr, "CRC error\n");
            crc_error = 1;
        }

        if (!crc_error) {
            char *pos = strstr(buffer, "t=");
            if (pos) {
                float temp = strtof(pos + 2, NULL) / 1000.0;
                printf("Temperature: %.3f°C\n", temp);
            }
        }

        close(fd);
        sleep(5);
    }

    return 0;
}

