#include <libgpiod.h>

#define GPIO_PIN 27
#define CYCLES 50
#define DELAY 100000 // 0.1 seconds

static int running = 1;

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    unsigned int value;
    int i;

    // Register signal handler
    signal(SIGINT, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO line as output
    if (gpiod_line_request_output(line, "myprog", 0) < 0) {
        fprintf(stderr, "Failed to set GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    for (i = 0; i < CYCLES && running; i++) {
        // Toggle GPIO line
        value = gpiod_line_get_value(line);
        gpiod_line_set_value(line, !value);

        // Report state
        printf("Cycle %d: %s\n", i + 1, value ? "High" : "Low");

        // Wait
        usleep(DELAY);
