        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "my_program", state)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        state = !state;
        if (gpiod_line_set_value(line, state)) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("State: %d\n", state);
