#include <signal.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_WTIME 0x03
#define TCS34725_AILTL 0x04
#define TCS34725_AILTH 0x05
#define TCS34725_AIHTL 0x06
#define TCS34725_AIHTH 0x07
#define TCS34725_PERS 0x0C
#define TCS34725_CONFIG 0x0D
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_STATUS 0x13
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

int file;
char *filename = "/dev/i2c-1";
__u8 buffer[2];

void cleanup(int signum) {
    close(file);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    signal(SIGINT, cleanup);

    while (1) {
        buffer[0] = TCS34725_COMMAND_BIT | TCS34725_CDATAL;
        if (write(file, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        uint16_t clear = (buffer[1] << 8) | buffer[0];

        buffer[0] = TCS34725_COMMAND_BIT | TCS34725_RDATAL;
        if (write(file, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        uint16_t red = (buffer[1] << 8) | buffer[0];

        buffer[0] = TCS34725_COMMAND_BIT | TCS34725_GDATAL;
        if (write(file, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        uint16_t green = (buffer[1] << 8) | buffer[0];

        buffer[0] = TCS34725_COMMAND_BIT | TCS34725_BDATAL;
        if (write(file, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        uint16_t blue = (buffer[1] << 8) | buffer[0];

        printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

        usleep(200000);
    }

    return 0;
}

