        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_5);
        goto close_chip;
    }

    signal(SIGINT, sig_handler);

    while (running) {
        ret = gpiod_line_set_value(line2, 1);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_2);
            goto close_lines;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN_2);

        ret = gpiod_line_set_value(line3, 0);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_3);
            goto close_lines;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN_3);

        ret = gpiod_line_set_value(line5, 1);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_5);
            goto close_lines;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN_5);

        sleep(5);
    }

    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_line_release(line5);

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

close_lines:
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_line_release(line5);

close_chip:
    gpiod_chip_close(chip);

    return EXIT_FAILURE;
}

