#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 23
#define LED_PIN 24

static bool keep_running = true;

static void sig_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = false;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request TRIG_PIN as output
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04 TRIG";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    line = gpiod_chip_get_line(chip, TRIG_PIN);
    ret = gpiod_line_request(line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request TRIG_PIN as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request ECHO_PIN as input
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04 ECHO";
    request.request_type = GPIOD_LINE_REQUEST_INPUT;
    line = gpiod_chip_get_line(chip, ECHO_PIN);
    ret = gpiod_line_request(line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request ECHO_PIN as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED_PIN as output
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04 LED";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    line = gpiod_chip_get_line(chip, LED_PIN);
    ret = gpiod_line_request(line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request LED_PIN as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);

    while (keep_running) {
        // Trigger the sensor
        gpiod_line_set_value(line, 1);
        usleep(10);
        gpiod_line_set_value(line, 0);

        // Wait for the echo
        struct gpiod_waiter *waiter = gpiod_line_waiter_new(line, GPIOD_LINE_EVENT_BOTH_EDGES, 0);
        ret = gpiod_line_event_wait(line, waiter, -1);
        gpiod_waiter_free(waiter);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for ECHO_PIN\n");
            break;
        }

        // Read the state of the LED
        int led_state = gpiod_line_get_value(line);
        printf("LED state: %d\n", led_state);

        // Sleep for a bit
        usleep(200000);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

