#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONVERSION 0x01
#define ADS1115_CONFIG 0x01
#define ADS1115_DRDY 4

int main() {
    int file;
    uint8_t buffer[2];
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;

    // Open the I2C bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Connect to the ADS1115
    if (ioctl(file, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to connect to the ADS1115");
        close(file);
        return EXIT_FAILURE;
    }

    // Configure the ADS1115
    buffer[0] = ADS1115_CONFIG;
    buffer[1] = ADS1115_CONVERSION;
    write(file, buffer, 2);

    // Request GPIO interrupt
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(file);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, ADS1115_DRDY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(file);
        return EXIT_FAILURE;
    }

    // Set up the GPIO interrupt
    if (gpiod_line_request_irq(line, GPIOD_LINE_REQUEST_FLAG_BOUNCE, NULL, NULL, NULL) < 0) {
        perror("Failed to request GPIO interrupt");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        close(file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for the interrupt
        if (gpiod_line_event_wait(line, &event) < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        // Read the ADC value
        if (read(file, buffer, 2) != 2) {
            perror("Failed to read ADC value");
            break;
        }

        // Print the ADC value
        printf("ADC value: %d\n", (buffer[0] << 8) | buffer[1]);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(file);

    return EXIT_SUCCESS;
}

