#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define MPU6050_ADDRESS 0x68
#define READ_LENGTH 14

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    char buffer[READ_LENGTH];
    int result;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    for (int i = 0; i < 100; i++) {
        result = read(file, buffer, READ_LENGTH);

        if (result != READ_LENGTH) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        printf("Reading %d: Accel X: %d, Accel Y: %d, Accel Z: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n",
               i + 1,
               (buffer[0] << 8) | buffer[1],
               (buffer[2] << 8) | buffer[3],
               (buffer[4] << 8) | buffer[5],
               (buffer[8] << 8) | buffer[9],
               (buffer[10] << 8) | buffer[11],
               (buffer[12] << 8) | buffer[13]);
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>

#define GPIO_PIN_14 14
#define GPIO_PIN_15 15
#define SLEEP_TIME 5

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line14, *line15;
    enum gpiod_line_value value;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_PIN_14);
    if (!line14) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_14);
        goto close_chip;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_PIN_15);
    if (!line15) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_15);
        goto release_line14;
    }

    ret = gpiod_line_request_output(line14, "my-output", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output for GPIO %d\n", GPIO_PIN_14);
        goto release_line15;
    }

    ret = gpiod_line_request_output(line15, "my-output", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output for GPIO %d\n", GPIO_PIN_15);
        goto release_line14;
    }

    while (true) {
        ret = gpiod_line_set_value(line14, 1);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_14);
            goto release_line15;
        }

        ret = gpiod_line_set_value(line15, 1);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_15);
            goto release_line14;
        }

        printf("GPIO %d and %d set to 1\n", GPIO_PIN_14, GPIO_PIN_15);

        sleep(SLEEP_TIME);

        ret = gpiod_line_set_value(line14, 0);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_14);
            goto release_line15;
        }

        ret = gpiod_line_set_value(line15, 0);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PIN_15);
            goto release_line14;
        }

        printf("GPIO %d and %d set to 0\n", GPIO_PIN_14, GPIO_PIN_15);

        sleep(SLEEP_TIME);
    }

release_line15:
    gpiod_line_release(line15);
release_line14:
    gpiod_line_release(line14);
close_chip:
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <mosquitto.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define MQTT_TOPIC "sensor/reading"
#define MQTT_BROKER "mqtt.example.com"

static int run = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct mosquitto *mosq;

void publish_reading(float reading) {
    char payload[50];
    sprintf(payload, "%f", reading);
    mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
}

void handle_interrupt(int signum) {
    run = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_interrupt;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if(mosq == NULL) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    if(mosquitto_connect(mosq, MQTT_BROKER, 1883, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Unable to connect to MQTT broker.\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if(!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip.\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if(!line) {
        fprintf(stderr, "Error: Unable to get GPIO line.\n");
        return 1;
    }

    if(gpiod_line_request_input(line, "sensor_reading") < 0) {
        fprintf(stderr, "Error: Unable to request GPIO line as input.\n");
        return 1;
    }

    while(run) {
        float reading = gpiod_line_get_value(line);
        publish_reading(reading);
        usleep(10000); // sleep for 0.01 seconds
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 23
#define INTERVAL 5

static bool keep_running = true;

static void sig_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = false;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Can't catch SIGINT\n");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line request
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Toggle GPIO line
        ret = gpiod_line_set_value(line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN);

        sleep(INTERVAL);

        ret = gpiod_line_set_value(line, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);

        sleep(INTERVAL);
    }

    // Release line
    gpiod_line_release(line);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 22
#define TIMEOUT 50000 // 50ms timeout

static bool running = true;

void interrupt_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line_trig, *line_echo;
    uint64_t start, end, duration;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request TRIG pin
    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get TRIG pin\n");
        goto cleanup;
    }

    gpiod_line_request_input(&request, "TRIG");
    if (gpiod_line_request(line_trig, &request)) {
        fprintf(stderr, "Failed to request TRIG pin\n");
        goto cleanup;
    }

    // Request ECHO pin
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get ECHO pin\n");
        goto cleanup;
    }

    gpiod_line_request_input(&request, "ECHO");
    if (gpiod_line_request(line_echo, &request)) {
        fprintf(stderr, "Failed to request ECHO pin\n");
        goto cleanup;
    }

    // Set up interrupt handler
    signal(SIGINT, interrupt_handler);

    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(line_trig, 1);
        usleep(10);
        gpiod_line_set_value(line_trig, 0);

        // Wait for the ECHO pin to go high
        while (!gpiod_line_get_value(line_echo)) {
            if (gpiod_line_event_wait(line_echo, TIMEOUT)) {
                fprintf(stderr, "Timeout waiting for ECHO pin to go high\n");
                goto cleanup;
            }
        }

        // Record the start time
        start = gpiod_line_event_get_time_ns();

        // Wait for the ECHO pin to go low
        while (gpiod_line_get_value(line_echo)) {
            if (gpiod_line_event_wait(line_echo, TIMEOUT)) {
                fprintf(stderr, "Timeout waiting for ECHO pin to go low\n");
                goto cleanup;
            }
        }

        // Record the end time
        end = gpiod_line_event_get_time_ns();

        // Calculate the duration
        duration = end - start;

        // Check the validity of the reading
        if (duration > 0 && duration < 20000000) { // 20ms max
            // Convert the duration to distance (in cm)
            float distance = duration / 58.0;

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Invalid reading\n");
        }

        // Wait for 0.1 seconds
        usleep(100000);
    }

cleanup:
    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

