        if (gpiod_line_get_value(line, &value) != 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            gpiod_chip_close(chip);
            gpiod_line_release(line);
            mosquitto_destroy(mosq);
            return EXIT_FAILURE;
