#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define MAX_WAIT_TIME 5000000 // 5 seconds

static bool keep_running = true;

void intHandler(int dummy) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line_trig, *line_echo;
    uint64_t start_time, end_time, duration;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request TRIG pin
    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get TRIG pin\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request ECHO pin
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get ECHO pin\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set TRIG pin as output
    ret = gpiod_line_request_output(line_trig, "HC-SR04 TRIG", 0);
    if (ret) {
        fprintf(stderr, "Failed to set TRIG pin as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set ECHO pin as input
    ret = gpiod_line_request_input(line_echo, "HC-SR04 ECHO");
    if (ret) {
        fprintf(stderr, "Failed to set ECHO pin as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up interrupt handler
    signal(SIGINT, intHandler);

    while (keep_running) {
        // Send trigger pulse
        gpiod_line_set_value(line_trig, 1);
        usleep(10);
        gpiod_line_set_value(line_trig, 0);

        // Wait for echo pulse
        start_time = gettime();
        while (gpiod_line_get_value(line_echo) == 0) {
            if (gettime() - start_time > MAX_WAIT_TIME) {
                fprintf(stderr, "Echo pulse timeout\n");
                break;
            }
            usleep(100);
        }

        // Measure echo pulse duration
        start_time = gettime();
        while (gpiod_line_get_value(line_echo) == 1) {
            if (gettime() - start_time > MAX_WAIT_TIME) {
                fprintf(stderr, "Echo pulse timeout\n");
                break;
            }
            usleep(100);
        }
        end_time = gettime();
        duration = end_time - start_time;

        // Calculate distance
        float distance = duration * 0.034 / 2.0;

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for next measurement
        usleep(200000);
    }

    // Release resources
    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

