int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int gpios[] = {17, 18, 22, 23};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output mode\n", gpios[i]);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (int i = 0; i < num_gpios; i++) {
            for (int duty = 0; duty <= 255; duty++) {
                if (gpioHardwarePWM(gpios[i], 1000, duty) < 0) {
                    fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpios[i]);
                    return EXIT_FAILURE;
                }
                printf("GPIO %d: %d\n", gpios[i], duty);
                sleep(1);
            }
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <signal.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/reading"
#define DEVICE_PATH "/dev/sensor"

bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    struct mosquitto *mosq = NULL;
    int rc = 0;
    int sensor_fd = -1;
    char reading[10];
    bool valid_reading = false;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Create a new mosquitto client
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    // Connect to the MQTT broker
    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Unable to connect to MQTT broker.\n");
        goto cleanup;
    }

    // Open the sensor device
    sensor_fd = open(DEVICE_PATH, O_RDONLY);
    if (sensor_fd < 0) {
        fprintf(stderr, "Error: Unable to open sensor device.\n");
        goto cleanup;
    }

    // Read sensor readings and publish to MQTT
    while (running) {
        // Simulate reading from the sensor device
        memset(reading, 0, sizeof(reading));
        sprintf(reading, "%d", rand() % 100);

        // Validate the reading
        valid_reading = (atoi(reading) >= 0 && atoi(reading) <= 100);
        if (!valid_reading) {
            fprintf(stderr, "Error: Invalid sensor reading.\n");
            continue;
        }

        // Publish the reading to the MQTT topic
        rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(reading), reading, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error: Unable to publish to MQTT topic.\n");
            break;
        }

        // Sleep for a bit before reading again
        sleep(1);
    }

cleanup:
    // Disconnect from the MQTT broker
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }

    // Close the sensor device
    if (sensor_fd >= 0) {
        close(sensor_fd);
    }

    return rc != MOSQ_ERR_SUCCESS;
}

