#include <sys/stat.h>
#include <fcntl.h>
#include <mosquitto.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define MQTT_TOPIC "sensor/reading"

static int i2c_fd;
static struct mosquitto *mosq;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    exit(signum);
}

int read_sensor() {
    uint16_t reading;
    if (write(i2c_fd, &ADS1115_CONVERSION_REG, 1) != 1) {
        return -1;
    }
    if (read(i2c_fd, &reading, 2) != 2) {
        return -1;
    }
    return reading;
}

void publish_reading(int reading) {
    char payload[10];
    sprintf(payload, "%d", reading);
    mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        perror("Failed to create Mosquitto client");
        return EXIT_FAILURE;
    }

    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        perror("Failed to connect to MQTT broker");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 10; i++) {
        int reading = read_sensor();
        if (reading < 0) {
            perror("Failed to read sensor");
            return EXIT_FAILURE;
        }
        publish_reading(reading);
        sleep(1);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define SLEEP_TIME 50 // in milliseconds

static bool keep_running = true;

void intHandler(int dummy) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line18;
    int ret;

    // Register interrupt handler
    signal(SIGINT, intHandler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line17 || !line18) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line 17 as output
    ret = gpiod_line_request_output(line17, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line 17 as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line 18 as output
    ret = gpiod_line_request_output(line18, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line 18 as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set line 17 to high
        ret = gpiod_line_set_value(line17, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line 17 to high\n");
            break;
        }

        // Set line 18 to high
        ret = gpiod_line_set_value(line18, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line 18 to high\n");
            break;
        }

        // Sleep for 0.05 seconds
        usleep(SLEEP_TIME * 1000);

        // Set line 17 to low
        ret = gpiod_line_set_value(line17, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line 17 to low\n");
            break;
        }

        // Set line 18 to low
        ret = gpiod_line_set_value(line18, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line 18 to low\n");
            break;
        }

        // Sleep for 0.05 seconds
        usleep(SLEEP_TIME * 1000);
    }

    // Release lines
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

