#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyS0"
#define _POSIX_SOURCE 1 /* POSIX compliant source */

volatile int stop;

void signal_handler_IO (int status);
void write_to_port(int fd, const char *str);

int main(int argc, char **argv)
{
    int fd;
    struct termios oldtio, newtio;
    char buf[255];
    int n;

    /* open the device */
    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    /* save current port settings */
    if (tcgetattr(fd, &oldtio) == -1) {
        perror("tcgetattr");
        exit(-1);
    }

    /* set new port settings for canonical input processing */
    memset(&newtio, 0, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical, no echo,...) */
    newtio.c_lflag = 0;

    /* set blocking */
    newtio.c_cc[VMIN]  = 1;
    newtio.c_cc[VTIME] = 0;

    /* activate the settings */
    if (tcsetattr(fd, TCSANOW, &newtio) == -1) {
        perror("tcsetattr");
        exit(-1);
    }

    /* install the signal handler before making the device asynchronous */
    signal(SIGIO, signal_handler_IO);
    fcntl(fd, F_SETOWN, getpid());
    fcntl(fd, F_SETFL, FASYNC);

    /* wait for input */
    while (1) {
        if(stop) {
            break;
        }
        n = read(fd, buf, sizeof(buf));
        if (n > 0) {
            buf[n] = 0;   /* set end of string */
            printf("%s", buf);
        }
    }

    /* restore old port settings */
    tcsetattr(fd, TCSANOW, &oldtio);

    /* close the device */
    close(fd);

    return 0;
}

void signal_handler_IO (int status)
{
    /* do nothing */
}

void write_to_port(int fd, const char *str)
{
    int n;

    n = write(fd, str, strlen(str));
    if (n < 0) {
        fputs("write error\n", stderr);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <signal.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_REG_TEMP_OUT 0x41
#define MPU6050_REG_GYRO_XOUT 0x43
#define MPU6050_REG_GYRO_YOUT 0x45
#define MPU6050_REG_GYRO_ZOUT 0x47
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_CONFIG 0x1A
#define MPU6050_REG_SMPLRT_DIV 0x19

static int fd;

void cleanup(int signum) {
    close(fd);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    uint8_t data[14];
    while (1) {
        if (write(fd, &MPU6050_REG_TEMP_OUT, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(fd, data, 14) != 14) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        int16_t temp = (data[0] << 8) | data[1];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Temperature: %d\n", temp);
        printf("Gyro X: %d\n", gyro_x);
        printf("Gyro Y: %d\n", gyro_y);
        printf("Gyro Z: %d\n", gyro_z);

        usleep(100000); // sleep for 0.1 seconds
    }

    return 0;
}

