#define GPIO_PIN 17
#define MQTT_TOPIC "sensor/reading"

static int run = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct mosquitto *mosq;

void exit_handler(int signum) {
    run = 0;
}

int main(int argc, char *argv[]) {
    char msg[128];
    int value;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create new MQTT client\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, exit_handler);

    // Main loop
    while (run) {
        // Read sensor value
        value = gpiod_line_get_value(line);
        sprintf(msg, "%d", value);

        // Publish to MQTT
        mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(msg), msg, 0, false);

        // Sleep for a bit
        sleep(1);
    }

    // Clean up
    mosquitto_destroy(mosq);
    gpiod_chip_close(chip);
    mosquitto_lib_cleanup();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    int gpios[] = {2, 3, 18, 23, 24};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < num_gpios; i++) {
        if (gpioSetPWMfrequency(gpios[i], 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(gpios[i], 100) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioPWM(gpios[i], 50) < 0) {
            fprintf(stderr, "Failed to set PWM value for GPIO %d\n", gpios[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Set PWM value for GPIO %d to 50\n", gpios[i]);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handler);

    int gpios[] = {17, 22, 27};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "failed to set GPIO %d mode\n", gpios[i]);
            return EXIT_FAILURE;
        }
    }

    int state = 0;
    while (!stop) {
        for (int i = 0; i < num_gpios; i++) {
            if (gpioWrite(gpios[i], state) < 0) {
                fprintf(stderr, "failed to write to GPIO %d\n", gpios[i]);
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", gpios[i], state);
        }
        state = !state;
        sleep(20); // sleep for 0.05 seconds
    }

    for (int i = 0; i < num_gpios; i++) {
        gpioWrite(gpios[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying device");
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    void *mem = malloc(buf.length);
    if (!mem) {
        perror("Error allocating memory");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        free(mem);
        close(fd);
        return 1;
    }

    while (1) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            free(mem);
            close(fd);
            return 1;
        }

        int image_fd = open(IMAGE_FILE, O_WRONLY | O_CREAT, 0666);
        if (image_fd < 0) {
            perror("Error opening image file");
            free(mem);
            close(fd);
            return 1;
        }

        if (write(image_fd, mem, buf.bytesused) < 0) {
            perror("Error writing image file");
            close(image_fd);
            free(mem);
            close(fd);
            return 1;
        }

        close(image_fd);
        sleep(1);
    }

    free(mem);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG
#define IMAGE_BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        close(fd);
        return 1;
    }

    void *image_buffer = malloc(IMAGE_BUFFER_SIZE);
    if (!image_buffer) {
        perror("Failed to allocate buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        free(image_buffer);
        close(fd);
        return 1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        free(image_buffer);
        close(fd);
        return 1;
    }

    if (read(fd, image_buffer, IMAGE_BUFFER_SIZE) < 0) {
        perror("Failed to read image");
        free(image_buffer);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        free(image_buffer);
        close(fd);
        return 1;
    }

    int out_fd = open("image.jpg", O_WRONLY | O_CREAT, 0666);
    if (out_fd < 0) {
        perror("Failed to open output file");
        free(image_buffer);
        close(fd);
        return 1;
    }

    if (write(out_fd, image_buffer, IMAGE_BUFFER_SIZE) < 0) {
        perror("Failed to write image");
        free(image_buffer);
        close(out_fd);
        close(fd);
        return 1;
    }

    close(out_fd);
    free(image_buffer);
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 2
#define GPIO_PIN2 3
#define SLEEP_TIME 0.5

static bool running = true;

static void sig_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request request;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);

    while (running) {
        ret = gpiod_line_set_value(line, 1);
