            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);

        sleep(SLEEP_TIME);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

