#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_18 18
#define GPIO_PIN_19 19
#define SLEEP_TIME 500000 // 0.5 seconds

static bool running = true;

void interrupt_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_18, *line_19;
    int value_18, value_19;

    // Register interrupt handler
    signal(SIGINT, interrupt_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    line_19 = gpiod_chip_get_line(chip, GPIO_PIN_19);
    if (!line_18 || !line_19) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line values
    value_18 = gpiod_line_request_value(line_18, "request_18", 0);
    value_19 = gpiod_line_request_value(line_19, "request_19", 0);
    if (value_18 < 0 || value_19 < 0) {
        fprintf(stderr, "Failed to request GPIO line values\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read line values
        value_18 = gpiod_line_get_value(line_18);
        value_19 = gpiod_line_get_value(line_19);

        // Print values
        printf("GPIO 18: %d, GPIO 19: %d\n", value_18, value_19);

        // Sleep
        usleep(SLEEP_TIME);
    }

    // Release lines
    gpiod_line_release(line_18);
    gpiod_line_release(line_19);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyS0"
#define _POSIX_SOURCE 1 /* POSIX compliant source */

volatile int stop;

void sig_handler(int signo)
{
    if (signo == SIGINT)
        stop = 1;
}

int main(void)
{
    struct termios oldtio, newtio;
    int fd;
    char buf[255];
    int n;

    if ( (fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK)) < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    if (tcgetattr(fd, &oldtio) == -1) {
        perror("tcgetattr");
        exit(-1);
    }

    bzero(&newtio, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical, no echo,...) */
    newtio.c_lflag = 0;

    newtio.c_cc[VTIME]    = 0;   /* inter-character timer unused */
    newtio.c_cc[VMIN]     = 1;   /* blocking read until 1 character arrives */

    /* 
     * VTIME e VMIN devono essere settati affinché le funzioni read e
     * write non restituiscano immediatamente, ciò significa che
     * read attende che venga ricevuto almeno un carattere prima di restituire
     * e write attende che venga spedito almeno un carattere prima di restituire.
     */

    tcflush(fd, TCIFLUSH);

    if (tcsetattr(fd, TCSANOW, &newtio) == -1) {
        perror("tcsetattr");
        exit(-1);
    }

    signal(SIGINT, sig_handler);

    stop = 0;
    while (!stop) {
        n = read(fd, buf, sizeof(buf));
        if (n > 0) {
            buf[n] = 0;   /* mark end of string */
            printf("%s", buf);
        }
    }

    if (tcsetattr(fd, TCSANOW, &oldtio) == -1) {
        perror("tcsetattr");
    }

    close(fd);
    return 0;
}

