#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 27
#define INTERVAL 2

static bool running = true;

static void sig_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Toggle GPIO line state
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            break;
        }

        // Report the state
        printf("GPIO %d is now %s\n", GPIO_PIN, gpiod_line_get_value(line) ? "high" : "low");

        // Wait for 2 seconds
        sleep(INTERVAL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    int gpios[] = {8, 9, 10, 11, 17};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output mode\n", gpios[i]);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_gpios; i++) {
        for (int duty = 0; duty <= 255; duty++) {
