                fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpios[i]);
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", gpios[i], duty);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    int i;
    int gpio[3] = {17, 18, 27};
    int state[3] = {0, 0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        if (gpioSetPWMfrequency(gpio[i], 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio[i]);
            goto cleanup;
        }

        if (gpioSetPWMrange(gpio[i], 100) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", gpio[i]);
            goto cleanup;
        }
    }

    while (1) {
        for (i = 0; i < 3; i++) {
            if (gpioSetPWMdutycycle(gpio[i], state[i]) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio[i]);
                goto cleanup;
            }

            printf("GPIO %d: %d\n", gpio[i], state[i]);
            state[i] = (state[i] + 10) % 101;
        }

        sleep(500);
    }

cleanup:
    gpioTerminate();
    return EXIT_FAILURE;
}

