    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return false;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return false;
    }

    ret = gpiod_line_request_input(line, "dht22");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return false;
    }

    ret = gpiod_line_event_wait(line, &event);
    if (ret < 0) {
        fprintf(stderr, "Failed to wait for GPIO line event\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return false;
    }

    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        fprintf(stderr, "Unexpected GPIO line event type\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return false;
    }

    // TODO: Implement DHT22 data reading and validation

    gpiod_chip_close(chip);
    gpiod_line_release(line);

    return true;
}

