#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <paho-mqtt/mqtt.h>

#define CHANNEL 0
#define RANGE 1024
#define SPI_SPEED 500000
#define MCP3008_CS 8

int main(int argc, char **argv) {
    if (wiringPiSetup() == -1) {
        printf("Unable to setup wiringPi\n");
        return 1;
    }

    if (wiringPiSPISetup(CHANNEL, SPI_SPEED) == -1) {
        printf("Unable to setup SPI\n");
        return 1;
    }

    if (wiringPiSPIGetChannel(CHANNEL) != CHANNEL) {
        printf("Unable to get SPI channel\n");
        return 1;
    }

    if (wiringPiSPISetSpeed(CHANNEL, SPI_SPEED) != SPI_SPEED) {
        printf("Unable to set SPI speed\n");
        return 1;
    }

    if (wiringPiSPISetMode(CHANNEL, 0) != 0) {
        printf("Unable to set SPI mode\n");
        return 1;
    }

    if (wiringPiSPICS(MCP3008_CS) == -1) {
        printf("Unable to set CS pin\n");
        return 1;
    }

    int fd = wiringPiSPIGetFd(CHANNEL);
    if (fd == -1) {
        printf("Unable to get SPI file descriptor\n");
        return 1;
    }

    uint8_t tx[] = {1, 0, 0};
    uint8_t rx[3];

    if (read(fd, rx, sizeof(rx)) != sizeof(rx)) {
        printf("Unable to read from SPI\n");
        return 1;
    }

    int reading = ((rx[1] & 0x0F) << 8) | rx[2];
    if (reading < 0 || reading > RANGE) {
        printf("Invalid reading from MCP3008\n");
        return 1;
    }

    printf("Sensor reading: %d\n", reading);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV format

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return 1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    unsigned char buffer[IMAGE_SIZE];
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    buf.length = IMAGE_SIZE;
    buf.m = (struct v4l2_mbuffer *)buffer;
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        close(fd);
        return 1;
    }

    int out_fd = open("image.yuv", O_WRONLY | O_CREAT, 0666);
    if (out_fd < 0) {
        perror("Failed to open output file");
        close(fd);
        return 1;
    }

    if (write(out_fd, buffer, IMAGE_SIZE) != IMAGE_SIZE) {
        perror("Failed to write to output file");
        close(fd);
        close(out_fd);
        return 1;
    }

    close(out_fd);
    close(fd);
    return 0;
}

