#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define CYCLES 3

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_17, *line_18;
    unsigned int value;
    int i;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line_17) {
        fprintf(stderr, "Failed to get line for GPIO 17\n");
        goto close_chip;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        fprintf(stderr, "Failed to get line for GPIO 18\n");
        goto release_line_17;
    }

    if (gpiod_line_request_output(line_17, "myprog", 0)) {
        fprintf(stderr, "Failed to request line 17 as output\n");
        goto release_line_18;
    }

    if (gpiod_line_request_output(line_18, "myprog", 0)) {
        fprintf(stderr, "Failed to request line 18 as output\n");
        goto release_line_17;
    }

    for (i = 0; i < CYCLES; i++) {
        value = i % 2;
        gpiod_line_set_value(line_17, value);
        gpiod_line_set_value(line_18, !value);
        printf("Cycle %d: GPIO 17 = %d, GPIO 18 = %d\n", i + 1, value, !value);
    }

    gpiod_line_release(line_17);
    gpiod_line_release(line_18);

release_line_18:
    gpiod_line_release(line_18);

release_line_17:
    gpiod_line_release(line_17);

close_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

