#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define INTERVAL 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int state = 0;

void cleanup_and_exit(int exit_code) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    exit(exit_code);
}

void interrupt_handler(int signum) {
    cleanup_and_exit(0);
}

int main() {
    struct gpiod_line_request request = {
        .consumer = "gpio_output_toggle",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_vals = { 0 },
    };

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(line, &request, NULL)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, interrupt_handler);

    while (1) {
        if (gpiod_line_set_value(line, state)) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        printf("GPIO %d state: %d\n", GPIO_PIN, state);
        state = !state;
        sleep(INTERVAL);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
