#define NUM_PINS 6
int pin_numbers[NUM_PINS] = {4, 17, 22, 23, 24, 27};

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    struct gpiod_line_event event;
    int i, ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.num_lines = NUM_PINS;
    lines.lines = (struct gpiod_line **)malloc(sizeof(struct gpiod_line *) * NUM_PINS);
    if (!lines.lines) {
        fprintf(stderr, "Failed to allocate memory for lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines.lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines.lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", pin_numbers[i]);
            gpiod_chip_close(chip);
            free(lines.lines);
            return EXIT_FAILURE;
        }
    }

    ret = gpiod_line_request_output_bulk(&lines, "my_program", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output lines\n");
        gpiod_chip_close(chip);
        free(lines.lines);
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_set_value(lines.lines[i], 1);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", pin_numbers[i]);
        } else {
            printf("Set GPIO %d high\n", pin_numbers[i]);
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_set_value(lines.lines[i], 0);
        if (ret) {
            fprintf(stderr, "Failed to set value for GPIO %d\n", pin_numbers[i]);
        } else {
            printf("Set GPIO %d low\n", pin_numbers[i]);
        }
    }

    gpiod_line_release_bulk(&lines);
    free(lines.lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

