#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 18

static bool running = true;

static void sig_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_trig, *line_echo;
    struct gpiod_line_request request;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto close_chip;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get echo line\n");
        goto close_chip;
    }

    ret = gpiod_line_request_output(line_trig, "trigger", 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        goto close_chip;
    }

    ret = gpiod_line_request_input(line_echo, "echo");
    if (ret) {
        fprintf(stderr, "Failed to request echo line as input\n");
        goto close_chip;
    }

    signal(SIGINT, sig_handler);

    while (running) {
        gpiod_line_set_value(line_trig, 1);
        usleep(10);
        gpiod_line_set_value(line_trig, 0);

        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(line_echo, &event);
        if (ret) {
            fprintf(stderr, "Failed to wait for echo event\n");
            break;
        }

        printf("Echo received\n");
        sleep(1);
    }

    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);

close_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

void exit_handler(int signum) {
    printf("Exiting...\n");
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    int gpios[] = {8, 9, 11, 18};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            printf("Failed to set GPIO %d to output mode\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
    }

    int state = 0;
    while (1) {
        for (int i = 0; i < num_gpios; i++) {
            if (gpioWrite(gpios[i], state) < 0) {
                printf("Failed to write to GPIO %d\n", gpios[i]);
                gpioTerminate();
                return 1;
            }
        }
        printf("State: %d\n", state);
        state = !state;
        sleep(1);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_JPEG
#define IMAGE_JPEG_QUALITY 90

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    struct v4l2_streamparm streamparm;
    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = 10; // 0.1 seconds

    if (ioctl(fd, VIDIOC_S_PARM, &streamparm) < 0) {
        perror("Failed to set frame rate");
        close(fd);
        return 1;
    }

    while (1) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Failed to dequeue buffer");
            break;
        }

        int out_fd = open("image.jpg", O_WRONLY | O_CREAT, 0666);
        if (out_fd < 0) {
            perror("Failed to open output file");
            break;
        }

        char buffer[buf.bytesused];
        if (read(fd, buffer, buf.bytesused) != buf.bytesused) {
            perror("Failed to read buffer");
            close(out_fd);
            break;
        }

        if (write(out_fd, buffer, buf.bytesused) != buf.bytesused) {
            perror("Failed to write to output file");
            close(out_fd);
            break;
        }

        close(out_fd);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            break;
        }
    }

    close(fd);
    return 0;
}

#include <stdio.h>
