#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24
#define PERIOD 1000000 // 1 second

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_18, PERIOD) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_23, PERIOD) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO 23\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_24, PERIOD) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO 24\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        for (int i = 0; i <= 255; i++) {
            gpioPWM(GPIO_18, i);
            gpioPWM(GPIO_23, i);
            gpioPWM(GPIO_24, i);
            usleep(100000); // 0.1 seconds
        }

        for (int i = 255; i >= 0; i--) {
            gpioPWM(GPIO_18, i);
            gpioPWM(GPIO_23, i);
            gpioPWM(GPIO_24, i);
            usleep(100000); // 0.1 seconds
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define TRIG 17
#define ECHO 18

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line_trig, *line_echo;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_trig = gpiod_chip_get_line(chip, TRIG);
    if (!line_trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto close_chip;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO);
    if (!line_echo) {
        fprintf(stderr, "Failed to get echo line\n");
        goto close_chip;
    }

    ret = gpiod_line_request_output(line_trig, "trigger", 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        goto close_chip;
    }

    ret = gpiod_line_request_input(line_echo, "echo");
    if (ret) {
        fprintf(stderr, "Failed to request echo line as input\n");
        goto close_chip;
    }

    // Trigger the sensor
    gpiod_line_set_value(line_trig, 1);
    usleep(10); // Wait for 10 microseconds
    gpiod_line_set_value(line_trig, 0);

    // Wait for the echo line to go high
    while (gpiod_line_get_value(line_echo) == 0);

    // Measure the time it takes for the echo line to go low
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line_echo) == 1);
    clock_gettime(CLOCK_MONOTONIC, &end);

    double time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    double distance = time * 34000 / 2;

    printf("Distance: %.2f cm\n", distance);

    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

close_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

