#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <unistd.h>

#define MPU6050_ADDRESS 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    uint8_t buffer[14];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    while (1) {
        if (read(file, buffer, 14) != 14) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        accel_x = (buffer[0] << 8) | buffer[1];
        accel_y = (buffer[2] << 8) | buffer[3];
        accel_z = (buffer[4] << 8) | buffer[5];
        gyro_x = (buffer[8] << 8) | buffer[9];
        gyro_y = (buffer[10] << 8) | buffer[11];
        gyro_z = (buffer[12] << 8) | buffer[13];

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        printf("Gyro X: %d, Y: %d, Z: %d\n", gyro_x, gyro_y, gyro_z);

        usleep(100000); // sleep for 0.1 seconds
    }

    close(file);
    return 0;
}

