#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDRESS 0x44
#define SHT31_MEASURE_TEMP_HOLD_MASTER 0x06
#define SHT31_MEASURE_HUMIDITY_HOLD_MASTER 0x0D
#define SHT31_READ_USER_REG 0xE7
#define SHT31_WRITE_USER_REG 0xE6
#define SHT31_SOFT_RESET 0x30A2

#define SHT31_CRC_POLYNOMIAL 0x131

#define SHT31_STATUS_BUSY (1 << 7)

#define SHT31_MAX_RETRIES 5

#define SHT31_I2C_BUS "/dev/i2c-1"

static uint8_t sht31_crc8(const uint8_t data[], size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ SHT31_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static bool sht31_read_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return false;
    }
    for (size_t i = 0; i < len; ++i) {
        if (read(fd, data + i, 1) != 1) {
            return false;
        }
    }
    return true;
}

static bool sht31_write_reg(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    for (size_t i = 0; i < len; ++i) {
        buffer[i + 1] = data[i];
    }
    return write(fd, buffer, len + 1) == len + 1;
}

static bool sht31_measure(int fd, uint8_t command, uint16_t *value) {
    uint8_t buffer[3];
    for (int i = 0; i < SHT31_MAX_RETRIES; ++i) {
        if (!sht31_write_reg(fd, command, NULL, 0)) {
            return false;
        }
        usleep(100000); // Wait for measurement to complete
        if (!sht31_read_reg(fd, 0xFF, buffer, 3)) {
            return false;
        }
        if ((buffer[2] & SHT31_STATUS_BUSY) == 0) {
            uint16_t raw_value = (buffer[0] << 8) | buffer[1];
            *value = raw_value;
            return true;
        }
    }
    return false;
}

static bool sht31_read(int fd, uint16_t *temperature, uint16_t *humidity) {
    uint8_t buffer[2];
    if (!sht31_read_reg(fd, SHT31_READ_USER_REG, buffer, 2)) {
        return false;
    }
    uint8_t crc = sht31_crc8(buffer, 2);
    if (crc != 0) {
        return false;
    }
    if (!sht31_measure(fd, SHT31_MEASURE_TEMP_HOLD_MASTER, temperature)) {
        return false;
    }
    if (!sht31_measure(fd, SHT31_MEASURE_HUMIDITY_HOLD_MASTER, humidity)) {
        return false;
    }
    return true;
}

int main() {
    int fd = open(SHT31_I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return 1;
    }

    while (true) {
        uint16_t temperature, humidity;
        if (!sht31_read(fd, &temperature, &humidity)) {
            fprintf(stderr, "Failed to read from SHT31\n");
            close(fd);
            return 1;
        }
        printf("Temperature: %d.%02d°C, Humidity: %d.%02d%%\n",
               temperature / 100, temperature % 100,
               humidity / 100, humidity % 100);
        sleep(5);
    }

    close(fd);
    return 0;
}

