    }

    for (i = 0; i < 4; i++) {
        if (gpioSetPWMfrequency(gpio[i], 1000) < 0) {
            printf("Failed to set PWM frequency for GPIO %d\n", gpio[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(gpio[i], 100) < 0) {
            printf("Failed to set PWM range for GPIO %d\n", gpio[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMdutycycle(gpio[i], state[i]) < 0) {
            printf("Failed to set PWM duty cycle for GPIO %d\n", gpio[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < 4; i++) {
        printf("GPIO %d PWM state: %d\n", gpio[i], state[i]);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

