#define GPIO_PIN 24
#define PERIOD 50 // in milliseconds

static bool running = true;

static void sig_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Toggle GPIO line state
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Report the state
        printf("GPIO %d is now %d\n", GPIO_PIN, gpiod_line_get_value(line));

        // Wait for the next period
        usleep(PERIOD * 1000);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV format

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        close(fd);
        return 1;
    }

    void *mem = malloc(buf.length);
    if (!mem) {
        perror("Failed to allocate memory");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        free(mem);
        close(fd);
        return 1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        free(mem);
        close(fd);
        return 1;
    }

    FILE *file = fopen("image.yuv", "wb");
    if (!file) {
        perror("Failed to open file");
        free(mem);
        close(fd);
        return 1;
    }

    if (write(fd, mem, IMAGE_SIZE) < 0) {
        perror("Failed to write image");
        fclose(file);
        free(mem);
        close(fd);
        return 1;
    }

    fclose(file);
    free(mem);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

#include <stdio.h>
