#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

static bool keep_running = true;

void intHandler(int dummy) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request TRIG_PIN as output
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    line = gpiod_chip_get_line(chip, TRIG_PIN);
    ret = gpiod_line_request(line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request TRIG_PIN as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request ECHO_PIN as input
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04";
    request.request_type = GPIOD_LINE_REQUEST_INPUT;
    line = gpiod_chip_get_line(chip, ECHO_PIN);
    ret = gpiod_line_request(line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request ECHO_PIN as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED_PIN as output
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    line = gpiod_chip_get_line(chip, LED_PIN);
    ret = gpiod_line_request(line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request LED_PIN as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, intHandler);

    while (keep_running) {
        // Set TRIG_PIN to high
        gpiod_line_set_value(line, 1);

        // Wait for 10 microseconds
        usleep(10);

        // Set TRIG_PIN to low
        gpiod_line_set_value(line, 0);

        // Wait for ECHO_PIN to go high
        while (gpiod_line_get_value(line) == 0);

        // Record the time
        struct timespec start, current;
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Wait for ECHO_PIN to go low
        while (gpiod_line_get_value(line) == 1);

        // Calculate the time difference
        clock_gettime(CLOCK_MONOTONIC, &current);
        double time_diff = (current.tv_sec - start.tv_sec) * 1e9 + (current.tv_nsec - start.tv_nsec);

        // Calculate the distance
        double distance = time_diff * 0.034 / 2;

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Blink LED_PIN
        gpiod_line_set_value(line, 1);
        usleep(500000);
        gpiod_line_set_value(line, 0);
        usleep(500000);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

