#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_LIST {4, 17, 18}

int main() {
    int gpios[] = GPIO_LIST;
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);
    int i;
    int state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "failed to set GPIO %d to output mode\n", gpios[i]);
            goto cleanup;
        }
    }

    while (1) {
        for (i = 0; i < num_gpios; i++) {
            if (gpioPWM(gpios[i], 1024 * state) < 0) {
                fprintf(stderr, "failed to set PWM on GPIO %d\n", gpios[i]);
                goto cleanup;
            }
        }

        printf("State: %d\n", state);
        state = !state;
        sleep(1);
    }

cleanup:
    for (i = 0; i < num_gpios; i++) {
        gpioPWM(gpios[i], 0);
    }

    gpioTerminate();
    return EXIT_FAILURE;
}

