#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <time.h>

#define DHT22_PIN 4
#define DHT22_TIMEOUT 1000000 // 1 second timeout

bool read_dht22(int pin, float *temperature, float *humidity) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec start, current;
    int value, count, i;
    float sum_humidity = 0, sum_temperature = 0;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return false;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return false;
    }

    gpiod_line_request_input(line, "dht22");

    for (i = 0; i < 3; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        value = gpiod_line_get_value(line);

        while (value == gpiod_line_get_value(line)) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            if ((current.tv_sec - start.tv_sec) * 1000000000 + (current.tv_nsec - start.tv_nsec) > DHT22_TIMEOUT) {
                gpiod_chip_close(chip);
                return false;
            }
        }

        count = 0;
        while (gpiod_line_get_value(line) == value) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            if ((current.tv_sec - start.tv_sec) * 1000000000 + (current.tv_nsec - start.tv_nsec) > DHT22_TIMEOUT) {
                gpiod_chip_close(chip);
                return false;
            }
            count++;
        }

        if (i == 0) {
            sum_humidity = count;
        } else if (i == 1) {
            sum_temperature = count;
        } else if (i == 2) {
            *humidity = sum_humidity;
            *temperature = sum_temperature;
        }
    }

    gpiod_chip_close(chip);
    return true;
}

int main() {
    float temperature, humidity;

    if (read_dht22(DHT22_PIN, &temperature, &humidity)) {
        printf("Humidity: %.2f%%, Temperature: %.2fC\n", humidity, temperature);
    } else {
        printf("Failed to read DHT22 sensor\n");
    }

    return 0;
}

