#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define GPIO_NUMBERS 7
#define CYCLES 100
#define SLEEP_TIME 500000 // 0.5 seconds

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request request;
    int i, j;
    int values[GPIO_NUMBERS] = {0};

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.num_lines = GPIO_NUMBERS;
    lines.lines = (struct gpiod_line **)malloc(sizeof(struct gpiod_line *) * GPIO_NUMBERS);
    if (!lines.lines) {
        fprintf(stderr, "Failed to allocate memory for lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (i = 0; i < GPIO_NUMBERS; i++) {
        lines.lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines.lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", i);
            for (j = 0; j < i; j++) {
                gpiod_line_release(lines.lines[j]);
            }
            free(lines.lines);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    request.consumer = "gpio_output";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    request.flags = 0;

    for (i = 0; i < GPIO_NUMBERS; i++) {
        if (gpiod_line_request(&lines.lines[i], &request)) {
            fprintf(stderr, "Failed to request line %d\n", i);
            for (j = 0; j < i; j++) {
                gpiod_line_release(lines.lines[j]);
            }
            free(lines.lines);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < CYCLES; i++) {
        for (j = 0; j < GPIO_NUMBERS; j++) {
            values[j] = (values[j] + 1) % 2;
            gpiod_line_set_value(lines.lines[j], values[j]);
            printf("GPIO %d: %d\n", j, values[j]);
        }
        usleep(SLEEP_TIME);
    }

    for (i = 0; i < GPIO_NUMBERS; i++) {
        gpiod_line_release(lines.lines[i]);
    }

    free(lines.lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

