#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <libgpiod.h>

static bool keep_running = true;

static void sig_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = false;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for graceful exit
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Can't catch SIGINT\n");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line for GPIO 17
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line for GPIO 18
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, 18);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO 18\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Set line request flags
    struct gpiod_line_request_config config = {
        .consumer = "my_program",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .flags = 0
    };

    // Request line for output
    ret = gpiod_line_request(line, &config, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line for output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    // Request line for output
    ret = gpiod_line_request(line2, &config, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line for output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 17 to high
        ret = gpiod_line_set_value(line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO 17 to high\n");
            break;
        }
        printf("GPIO 17 set to high\n");

        // Set GPIO 18 to high
        ret = gpiod_line_set_value(line2, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO 18 to high\n");
            break;
        }
        printf("GPIO 18 set to high\n");

        // Wait for 1 second
        sleep(1);

        // Set GPIO 17 to low
        ret = gpiod_line_set_value(line, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO 17 to low\n");
            break;
        }
        printf("GPIO 17 set to low\n");

        // Set GPIO 18 to low
        ret = gpiod_line_set_value(line2, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO 18 to low\n");
            break;
        }
        printf("GPIO 18 set to low\n");

        // Wait for 1 second
        sleep(1);
    }

    // Release lines
    gpiod_line_release(line);
    gpiod_line_release(line2);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

