    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pwm = gpioPWMCreate(GPIO_PIN, 1000);
    if (pwm < 0) {
