#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handler);

    int gpios[] = {17, 18, 27};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output mode\n", gpios[i]);
            return EXIT_FAILURE;
        }
    }

    int state = 0;
    while (!stop) {
        for (int i = 0; i < num_gpios; i++) {
            if (gpioWrite(gpios[i], state) < 0) {
                fprintf(stderr, "Failed to write to GPIO %d\n", gpios[i]);
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", gpios[i], state);
        }
        state = !state;
        sleep(1);
    }

    for (int i = 0; i < num_gpios; i++) {
        gpioWrite(gpios[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_22 22
#define GPIO_PIN_23 23
#define GPIO_PIN_27 27

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;

static void cleanup_and_exit(int exit_code)
{
    gpiod_line_set_value_bulk(lines, 0);
    gpiod_chip_close(chip);
    exit(exit_code);
}

static void signal_handler(int signum)
{
    cleanup_and_exit(0);
}

int main(int argc, char *argv[])
{
    struct gpiod_line_request request = {
        .consumer = "gpio_output",
        .request_type = GPIO_LINE_REQUEST_OUTPUT,
    };

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.offsets[0] = GPIO_PIN_17;
    lines.offsets[1] = GPIO_PIN_22;
    lines.offsets[2] = GPIO_PIN_23;
    lines.offsets[3] = GPIO_PIN_27;
    lines.count = 4;

    if (gpiod_chip_get_lines(chip, &lines) < 0) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_bulk(lines, &request) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value_bulk(lines, 1 << i);
            printf("GPIO %d set to high\n", lines.offsets[i]);
            sleep(1);
            gpiod_line_set_value_bulk(lines, 0);
            printf("GPIO %d set to low\n", lines.offsets[i]);
            sleep(1);
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

