#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 27
#define PERIOD 100 // in milliseconds

static bool running = true;

static void sig_handler(int signum) {
    if (signum == SIGINT) {
        running = false;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line request
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Toggle GPIO line
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            break;
        }

        // Report state
        printf("GPIO %d is now %d\n", GPIO_PIN, gpiod_line_get_value(line));

        // Wait for next period
        usleep(PERIOD * 1000);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
