#define MAX31855_REG_RTD_MSB 0x00
#define MAX31855_REG_RTD_LSB 0x01
#define MAX31855_REG_CONFIG 0x02
#define MAX31855_REG_HFAULT 0x03
#define MAX31855_REG_LFAULT 0x04
#define MAX31855_REG_FAULT 0x05

#define MAX31855_CONFIG 0x80
#define MAX31855_HFAULT 0x7F
#define MAX31855_LFAULT 0x7F

#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 500000

int spi_fd;

void spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .delay_usecs = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to configure SPI device");
        exit(1);
    }
}

void spi_read(uint8_t reg, uint8_t *data) {
    uint8_t tx[3] = {0x03, reg, 0x00};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)data,
        .len = 3,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .delay_usecs = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI device");
        exit(1);
    }
}

int main() {
    spi_init();

    uint8_t data[3];
    spi_read(MAX31855_REG_RTD_MSB, data);

    int16_t temp = (data[1] << 8) | data[2];
    float voltage = temp * 0.25;
    float temperature = voltage * 100;

    printf("Temperature: %.2f°C\n", temperature);

    close(spi_fd);

    return 0;
}

