#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define TIMEOUT 5 // Timeout in seconds

static void cleanup(gpiod_chip *chip, gpiod_line *line_trig, gpiod_line *line_echo) {
    gpiod_line_set_value(line_trig, 0);
    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);
}

int main() {
    gpiod_chip *chip;
    gpiod_line *line_trig, *line_echo;
    struct gpiod_line_request_config config;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto cleanup;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get echo line\n");
        goto cleanup;
    }

    gpiod_line_request_config(&config, "HC-SR04", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    ret = gpiod_line_request(line_trig, &config, 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line\n");
        goto cleanup;
    }

    gpiod_line_request_config(&config, "HC-SR04", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    ret = gpiod_line_request(line_echo, &config, 0);
    if (ret) {
        fprintf(stderr, "Failed to request echo line\n");
        goto cleanup;
    }

    gpiod_line_set_value(line_trig, 1);
    usleep(10); // Wait for 10 microseconds
    gpiod_line_set_value(line_trig, 0);

    struct gpiod_waiter *waiter = gpiod_line_waiter_new(line_echo, G_IO_IN, 0);
    if (!waiter) {
        fprintf(stderr, "Failed to create waiter\n");
        goto cleanup;
    }

    struct timespec timeout = {TIMEOUT, 0};
    ret = gpiod_line_wait_simple(waiter, &timeout);
    if (ret == 0) {
        uint8_t value = gpiod_line_get_value(line_echo);
        printf("Sensor state: %s\n", value ? "High" : "Low");
    } else {
        printf("Sensor did not respond within timeout\n");
    }

    gpiod_line_waiter_free(waiter);

cleanup:
    cleanup(chip, line_trig, line_echo);
    return EXIT_SUCCESS;
}

