#define BMP280_I2C_ADDRESS 0x03
#define BMP280_REG_TEMP 0x2E
#define BMP280_REG_PRESS 0x34
#define BMP280_REG_ID 0xD0
#define BMP280_ID 0x58

int main() {
    int file;
    uint8_t buffer[6];
    int16_t raw_temp, raw_press;
    float temp, press;
    int i;

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    for (i = 0; i < 3; i++) {
        // Read temperature
        buffer[0] = BMP280_REG_TEMP;
        write(file, buffer, 1);
        usleep(45000);
        read(file, buffer, 2);
        raw_temp = (buffer[0] << 8) | buffer[1];

        // Read pressure
        buffer[0] = BMP280_REG_PRESS;
        write(file, buffer, 1);
        usleep(45000);
        read(file, buffer, 3);
        raw_press = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];

        // Convert raw data to temperature and pressure
        temp = (raw_temp / 16384.0) * 42.5 + (-39.6);
        press = (raw_press / 131072.0) * 1048576.0 - 2097152.0;

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);
    }

    close(file);
    return 0;
}

