int i2c_fd;

void cleanup(int signum) {
    close(i2c_fd);
    printf("Program interrupted, cleaning up...\n");
    exit(0);
}

int main() {
    uint16_t data;
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = cleanup;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave.\n");
        exit(1);
    }

    while (1) {
        if (read(i2c_fd, &data, 2) != 2) {
            printf("Failed to read from the device\n");
            exit(1);
        }

        printf("Sensor reading: %d\n", data);

        sleep(1); // sleep for 0.5 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyAMA0"
#define _POSIX_SOURCE 1 /* POSIX compliant source */
#define FALSE 0
#define TRUE 1

volatile int STOP = FALSE;

void signal_handler_IO(int status);
void write_to_port(int fd, const char *buf, int len);
void read_from_port(int fd, char *buf, int len);

int main(void) {
    int fd;
    struct termios oldtio, newtio;
    char buf[255];

    /* open the device */
    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    /* save current port settings */
    tcgetattr(fd, &oldtio);

    /* set new port settings for canonical input processing */
    bzero(&newtio, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical) */
    newtio.c_lflag = 0;
    newtio.c_cc[VTIME] = 0; /* inter-character timer unused */
    newtio.c_cc[VMIN] = 1;  /* blocking read until 1 character arrives */

    /* 
     * VTIME e VMIN devono essere settati affinché read() non bloccante
     * funzioni come atteso.
     */
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &newtio);

    /* install the signal handler before making the device asynchronous */
    signal(SIGIO, signal_handler_IO);
    fcntl(fd, F_SETOWN, getpid());
    fcntl(fd, F_SETFL, FASYNC);

    /* loop while waiting for input. normally we would do other things here */
    while (STOP == FALSE) {
        sleep(1);
    }

    /* restore old port settings */
    tcsetattr(fd, TCSANOW, &oldtio);

    /* close the device */
    close(fd);
    return 0;
}

void signal_handler_IO(int status) {
    char buf[255];
    int n;

    /* read data from the port */
    n = read(fd, buf, sizeof(buf));
    if (n > 0) {
        buf[n] = 0; /* null terminate the string */
        printf("%s", buf);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_WAIT_TIME 5000000 // 5 seconds

static bool keep_running = true;

void intHandler(int dummy) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_trig, *line_echo;
    struct timespec timeout;
    unsigned int level;
    int ret;

    signal(SIGINT, intHandler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(line_trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_trig, "HC-SR04 Trig", 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        gpiod_line_release(line_trig);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line_echo, "HC-SR04 Echo");
    if (ret) {
        fprintf(stderr, "Failed to request echo line as input\n");
        gpiod_line_release(line_trig);
        gpiod_line_release(line_echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        gpiod_line_set_value(line_trig, 1);
        nanosleep(&(struct timespec){0, 10}, NULL); // 10 ns
        gpiod_line_set_value(line_trig, 0);

        timeout.tv_sec = 0;
        timeout.tv_nsec = MAX_WAIT_TIME;
        ret = gpiod_line_wait_for_edge(line_echo, &timeout);
        if (ret == 0) {
            gpiod_line_get_value(line_echo, &level);
            printf("Echo pin state: %d\n", level);
        } else {
            printf("Timeout occurred\n");
            break;
        }
    }

    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

