#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define ADXL345_ADDRESS 0x53
#define ACCEL_XOUT 0x32
#define ACCEL_YOUT 0x34
#define ACCEL_ZOUT 0x36

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    uint8_t buffer[6];
    int16_t accel[3];

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    buffer[0] = ACCEL_XOUT;
    if (write(file, buffer, 1) != 1) {
        perror("Failed to write to the i2c bus");
        exit(1);
    }

    if (read(file, buffer, 6) != 6) {
        perror("Failed to read from the i2c bus");
        exit(1);
    }

    accel[0] = (buffer[1] << 8) | buffer[0];
    accel[1] = (buffer[3] << 8) | buffer[2];
    accel[2] = (buffer[5] << 8) | buffer[4];

    printf("X: %d\n", accel[0]);
    printf("Y: %d\n", accel[1]);
    printf("Z: %d\n", accel[2]);

    close(file);
    return 0;
}

