#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handler);

    int gpio = 18;
    int frequency = 50; // 50 Hz
    int range = 1024; // 10-bit range

    gpioSetPWMfrequency(gpio, frequency);
    gpioSetPWMDutyCycle(gpio, range / 2);

    while (!stop) {
        for (int i = 0; i < range; i++) {
            gpioSetPWMDutyCycle(gpio, i);
            gpioDelay(100000); // 0.1 seconds
        }
        for (int i = range - 1; i >= 0; i--) {
            gpioSetPWMDutyCycle(gpio, i);
            gpioDelay(100000); // 0.1 seconds
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

