#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_NUMBERS 8
int gpios[GPIO_NUMBERS] = {0, 1, 2, 3, 4, 5, 12, 17};

void cleanup() {
    for (int i = 0; i < GPIO_NUMBERS; i++) {
        if (gpios[i] >= 0) {
            gpiod_line_release(gpios[i]);
        }
    }
}

void exit_handler(int signum) {
    printf("Interrupt received, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request request;
    int ret;

    // Register exit handler
    signal(SIGINT, exit_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < GPIO_NUMBERS; i++) {
        gpios[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (gpios[i] < 0) {
            fprintf(stderr, "Failed to get line %d\n", gpios[i]);
            cleanup();
            return EXIT_FAILURE;
        }

        request.consumer = "gpio_output";
        request.request_type = GPIO_LINE_REQUEST_OUTPUT;
        ret = gpiod_line_request(gpios[i], &request, NULL);
        if (ret) {
            fprintf(stderr, "Failed to request line %d\n", gpios[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    // Set lines to output
    lines.lines = gpios;
    lines.num_lines = GPIO_NUMBERS;
    ret = gpiod_line_set_value_bulk(chip, &lines, 1);
    if (ret) {
        fprintf(stderr, "Failed to set lines to output\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < GPIO_NUMBERS; i++) {
            ret = gpiod_line_set_value(gpios[i], i % 2);
            if (ret) {
                fprintf(stderr, "Failed to set value on line %d\n", gpios[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Set GPIO %d to %d\n", gpios[i], i % 2);
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

