#include <stdbool.h>
#include <libgpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define MAX_WAIT_TIME 500000 // 500ms

static bool keep_running = true;

void intHandler(int dummy) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line_trig, *line_echo;
    uint8_t value;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request TRIG pin
    line_trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line_trig) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request ECHO pin
    line_echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line_echo) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, intHandler);

    // Set up TRIG pin
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_line_request(line_trig, &request);
    if (ret) {
        fprintf(stderr, "Failed to request TRIG line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up ECHO pin
    memset(&request, 0, sizeof(request));
    request.consumer = "HC-SR04";
    request.request_type = GPIOD_LINE_REQUEST_INPUT;
    ret = gpiod_line_request(line_echo, &request);
    if (ret) {
        fprintf(stderr, "Failed to request ECHO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Trigger the sensor
        gpiod_line_set_value(line_trig, 1);
        usleep(10); // Wait for 10us
        gpiod_line_set_value(line_trig, 0);

        // Wait for ECHO pin to go high
        struct timespec timeout = {0, MAX_WAIT_TIME};
        ret = gpiod_line_wait(line_echo, &timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for ECHO line\n");
            break;
        }

        // Read the value of ECHO pin
        value = gpiod_line_get_value(line_echo);
        printf("ECHO pin value: %d\n", value);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(line_trig);
    gpiod_line_release(line_echo);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

