#include <unistd.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_WTIME 0x03
#define TCS34725_AILTL 0x04
#define TCS34725_AILTH 0x05
#define TCS34725_AIHTL 0x06
#define TCS34725_AIHTH 0x07
#define TCS34725_PERS 0x0C
#define TCS34725_CONFIG 0x0D
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_STATUS 0x13
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

int main() {
    int file;
    uint8_t buffer[2];
    uint16_t data;

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    while (1) {
        // Enable the device
        buffer[0] = TCS34725_ENABLE;
        buffer[1] = 0x01;
        write(file, buffer, 2);

        // Read the clear channel data
        buffer[0] = TCS34725_CDATAL;
        read(file, buffer, 2);
        data = (buffer[1] << 8) | buffer[0];
        printf("Clear channel data: %d\n", data);

        // Read the red channel data
        buffer[0] = TCS34725_RDATAL;
        read(file, buffer, 2);
        data = (buffer[1] << 8) | buffer[0];
        printf("Red channel data: %d\n", data);

        // Read the green channel data
        buffer[0] = TCS34725_GDATAL;
        read(file, buffer, 2);
        data = (buffer[1] << 8) | buffer[0];
        printf("Green channel data: %d\n", data);

        // Read the blue channel data
        buffer[0] = TCS34725_BDATAL;
        read(file, buffer, 2);
        data = (buffer[1] << 8) | buffer[0];
        printf("Blue channel data: %d\n", data);

        sleep(1); // Wait for 1 second
    }

    close(file);
    return 0;
}

