        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line 17 (GPIO 17)
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line 24 (GPIO 24)
    struct gpiod_line_request req24 = {
        .consumer = "my_program",
        .request_type = GPIO_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_value = 0,
    };
    ret = gpiod_line_request(line, &req24, 0);
    if (ret) {
        fprintf(stderr, "Failed to request line 24\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line to high
    ret = gpiod_line_set_value(line, 1);
    if (ret) {
        fprintf(stderr, "Failed to set line to high\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
