    printf("Line 17 (GPIO 17) set to high\n");

    // Set the line to low
    ret = gpiod_line_set_value(line, 0);
    if (ret) {
        fprintf(stderr, "Failed to set line to low\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Line 17 (GPIO 17) set to low\n");

    // Release the line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    int gpio[3] = {2, 3, 18};
    int i;
    int state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        if (gpioSetPWMfrequency(gpio[i], 1000) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio[i]);
            return EXIT_FAILURE;
        }

        if (gpioSetPWMrange(gpio[i], 100) < 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", gpio[i]);
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (i = 0; i < 3; i++) {
            if (gpioPWM(gpio[i], state) < 0) {
                fprintf(stderr, "Failed to set PWM state for GPIO %d\n", gpio[i]);
                return EXIT_FAILURE;
            }
        }

        printf("PWM state: %d\n", state);
        state = (state + 10) % 100;

        sleep(5);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

