#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_18 18
#define GPIO_PIN_22 22
#define SLEEP_TIME 50 // in milliseconds

static int running = 1;

void interrupt_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret, state = 0;

    // Register interrupt handler
    signal(SIGINT, interrupt_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO line as output
    ret = gpiod_line_request_output(line, "my_program", state);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO line as output for GPIO_PIN_22
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_22);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "my_program", state);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Toggle GPIO line state
        state = !state;
        ret = gpiod_line_set_value(line, state);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_set_value(line2, state);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        printf("GPIO line state: %d\n", state);
        usleep(SLEEP_TIME * 1000); // sleep for 0.05 seconds
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_line_release(line2);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

