#define BAUDRATE B9600
#define MODEMDEVICE "/dev/ttyS0"
#define _POSIX_SOURCE 1 /* POSIX compliant source */
#define FALSE 0
#define TRUE 1

volatile int STOP = FALSE;

void signal_handler_IO(int status);
void write_to_port(int fd, const char *buf, int len);

int main(void)
{
    int fd;
    struct termios oldtio, newtio;
    char buf[255];
    int n;

    /* open the device */
    fd = open(MODEMDEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror(MODEMDEVICE);
        exit(-1);
    }

    /* save current port settings */
    tcgetattr(fd, &oldtio);

    /* set new port settings for canonical input processing */
    memset(&newtio, 0, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;

    /* set input mode (non-canonical, no echo,...) */
    newtio.c_lflag = 0;
    newtio.c_cc[VTIME] = 0;   /* inter-character timer unused */
    newtio.c_cc[VMIN] = 1;    /* blocking read until 1 character arrives */

    /* 
     * VTIME e VMIN devono essere settati per la select 
     * non bloccante a intervalli regolari di tempo
     */
    newtio.c_cc[VTIME] = 10;   /* inter-character timer unused */
    newtio.c_cc[VMIN] = 0;     /* blocking read until 1 character arrives */

    /* 
     * procedura di installazione del gestore di segnali 
     * per la gestione dello standard input (come SIGIO)
     */
    signal(SIGIO, signal_handler_IO);
    fcntl(fd, F_SETOWN, getpid());
    fcntl(fd, F_SETFL, FASYNC);

    /* 
     * abilitazione del driver di trasmissione 
     * e attivazione della ricezione
     */
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &newtio);

    /* main loop */
    while (STOP == FALSE) {
        /* 
         * attende che il driver di trasmissione abbia 
         * ricevuto un carattere
         */
        fd_set rfds;
        struct timeval tv;
        int retval;

        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        /* 
         * timeout dopo 1 secondo 
         * (non bloccante)
         */
        tv.tv_sec = 1;
        tv.tv_usec = 0;

        retval = select(fd + 1, &rfds, NULL, NULL, &tv);
        /* 
         * se il timeout scade 
         * o il driver di trasmissione ha ricevuto un carattere
         */
        if (retval) {
            n = read(fd, buf, sizeof(buf));
            write(STDOUT_FILENO, buf, n);
        }
    }

    /* 
     * annullamento della configurazione 
     * del driver di trasmissione 
     */
    tcsetattr(fd, TCSANOW, &oldtio);

    /* close the device */
    close(fd);
    return 0;
}

void signal_handler_IO(int status)
{
    /* 
     * gestione del segnale SIGIO 
     * (richiamata dal driver di trasmissione)
     */
    printf("Signal received\n");
}

void write_to_port(int fd, const char *buf, int len)
{
    /* 
     * scrive i dati nel driver di trasmissione 
     * (non bloccante)
     */
    write(fd, buf, len);
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <libgpiod.h>

static bool keep_running = true;

static void sig_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = false;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request output direction
    ret = gpiod_line_request_output(line, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Toggle GPIO line
        ret = gpiod_line_set_value(line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 3 set to 1\n");

        sleep(1);

        ret = gpiod_line_set_value(line, 0);
        if (ret) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO 3 set to 0\n");

        sleep(1);
    }

    // Release line
    gpiod_line_release(line);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>

#define TRIG_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    unsigned int value;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line for TRIG_PIN
    line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for TRIG_PIN\n");
        goto close_chip;
    }

    // Set TRIG_PIN as output
    ret = gpiod_line_request_output(line, "TRIG_PIN", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output for TRIG_PIN\n");
        goto release_line;
    }

    // Request line for ECHO_PIN
    line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for ECHO_PIN\n");
        goto close_chip;
    }

    // Set ECHO_PIN as input
    ret = gpiod_line_request_input(line, "ECHO_PIN");
    if (ret) {
        fprintf(stderr, "Failed to request input for ECHO_PIN\n");
        goto release_line;
    }

    // Request line for LED_PIN
    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for LED_PIN\n");
        goto close_chip;
    }

    // Set LED_PIN as output
    ret = gpiod_line_request_output(line, "LED_PIN", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output for LED_PIN\n");
        goto release_line;
    }

    // Set TRIG_PIN high for 10us
    gpiod_line_set_value(line, 1);
    usleep(10000);

    // Set TRIG_PIN low
    gpiod_line_set_value(line, 0);

    // Wait for ECHO_PIN to go high
    while (gpiod_line_get_value(line) == 0);

    // Measure the pulse width
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) == 1);
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate distance
    double distance = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
    distance = distance / 58.0;

    // Print the distance
    printf("Distance: %.2f cm\n", distance);

    // Set LED_PIN high if distance is less than 50 cm
    if (distance < 50) {
        gpiod_line_set_value(line, 1);
    } else {
        gpiod_line_set_value(line, 0);
    }

    // Release lines
release_line:
    gpiod_line_release(line);

close_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define GPIO_PIN 18

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "myprog", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO line value\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO pin %d is %s\n", GPIO_PIN, value ? "high" : "low");

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handler);

    int gpio = 18;
    int frequency = 50;
    int dutyCycle = 128;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioPWM(gpio, frequency);

    while (!stop) {
        gpioServo(gpio, dutyCycle);
        printf("Duty cycle: %d\n", dutyCycle);
        sleep(1);
        dutyCycle = (dutyCycle + 64) % 256;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line 17 (GPIO 17)
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line 18 (GPIO 18)
    struct gpiod_line_request req18 = {
        .consumer = "my_program",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .default_value = 0,
    };
    ret = gpiod_line_request(line, &req18);
    if (ret) {
        fprintf(stderr, "Failed to request line 18\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line to high
    ret = gpiod_line_set_value(line, 1);
    if (ret) {
        fprintf(stderr, "Failed to set line 18 to high\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Line 18 set to high\n");

    // Release the line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

static int running = 1;

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_18, *line_23, *line_24;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line_18 || !line_23 || !line_24) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_18, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line 18 as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_23, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line 23 as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_24, "myprog", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line 24 as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);

    while (running) {
        gpiod_line_set_value(line_18, 1);
        gpiod_line_set_value(line_23, 1);
        gpiod_line_set_value(line_24, 1);
        printf("GPIO 18, 23, 24 set to 1\n");
        sleep(1);

        gpiod_line_set_value(line_18, 0);
        gpiod_line_set_value(line_23, 0);
        gpiod_line_set_value(line_24, 0);
        printf("GPIO 18, 23, 24 set to 0\n");
        sleep(1);
    }

    gpiod_line_release(line_18);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <signal.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

int file;
char *filename = "/dev/i2c-1";
int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

void exit_handler(int signum) {
    printf("Exiting...\n");
    close(file);
    exit(signum);
}

int main() {
    if ((file = open(filename, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave\n");
        exit(1);
    }

    signal(SIGINT, exit_handler);

    while (1) {
        char buffer[14];
        if (read(file, buffer, 14) != 14) {
            printf("Failed to read from the MPU6050\n");
            exit(1);
        }

        accel_x = (buffer[0] << 8) | buffer[1];
        accel_y = (buffer[2] << 8) | buffer[3];
        accel_z = (buffer[4] << 8) | buffer[5];
        gyro_x = (buffer[8] << 8) | buffer[9];
        gyro_y = (buffer[10] << 8) | buffer[11];
        gyro_z = (buffer[12] << 8) | buffer[13];

        printf("Accel: %d, %d, %d\n", accel_x, accel_y, accel_z);
        printf("Gyro: %d, %d, %d\n", gyro_x, gyro_y, gyro_z);

        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define INTERVAL 600 // 0.6 seconds

static bool running = true;

void interrupt_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec sleep_time = {0, INTERVAL * 1000 * 1000}; // 0.6 seconds

    // Register interrupt handler
    signal(SIGINT, interrupt_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request output direction
    if (gpiod_line_request_output(line, "myprog", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Toggle GPIO state
        if (gpiod_line_set_value(line, !gpiod_line_get_value(line))) {
            fprintf(stderr, "Failed to set GPIO line value\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Report state
        printf("GPIO state: %d\n", gpiod_line_get_value(line));

        // Sleep
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
